// AUTO-GENERATED 10-YEAR+ THANE MULTI-SPECTRAL DATASET & PINN MODEL ENGINE
// Exact Dataset: 2,304 monthly observations (2016-01 to 2026-08) across all 18 Thane municipal wards.
// Trained with PyTorch Physics-Informed Neural Network (PINN) implementing Surface Energy Balance & Automatic Differentiation PDEs.

export interface ThaneDatasetRecord {
  yearMonth: string
  year: number
  month: number
  monthName: string
  ward: string
  areaId: string
  location: string
  zoneType: string
  riskLevel: 'HIGH' | 'MODERATE' | 'LOW' | string
  lat: number
  lon: number
  avgLST: number
  actualLST: number
  pinnPredictedLST: number
  rfPredictedLST: number
  residualError: number
  monthDataSource: string
  ndvi: number
  ndbi: number
  ndwi: number
  albedo: number
  dataAvailable: boolean
  period: string
}

export interface ZoneMetricSummary {
  ward: string
  areaId: string
  areaName: string
  zoneType: string
  vulnerability: string
  lat: number
  lon: number
  recordsCount: number
  avgLST: number
  maxLST: number
  minLST: number
  avgNDVI: number
  avgNDBI: number
  pinnMAE: number
  pinnRMSE: number
  rfMAE: number
  rfRMSE: number
  improvement: string
}

export interface PINNBenchmarkResults {
  modelMetadata: {
    architecture: string
    lossFunction: string
    trainingSamples: number
    testSamples: number
    totalRecords: number
    zonesCount: number
    period: string
    physicsConstraints: string[]
    optimizer: string
    epochs: number
  }
  benchmark: {
    pinn: {
      mae: number
      rmse: number
      r2: number
      maxError: number
      heatwaveAccuracy: string
      physicsConsistency: string
      inferenceLatencyMs: number
    }
    randomForest: {
      mae: number
      rmse: number
      r2: number
      maxError: number
      heatwaveAccuracy: string
      physicsConsistency: string
      inferenceLatencyMs: number
    }
  }
  zoneMetrics: ZoneMetricSummary[]
}

